local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['cal'] = function()
-- Calendar pieces shared by the app (src/main.lua) and the lock screen (lockscreen.lua, which
-- carries its own copy: lock entries load alone): dates without `os`, an iCalendar (RFC 5545
-- subset) reader that keeps only what is near today, recurrence, the per-calendar cache and the
-- calendar list. A port of KOReader's calendar.koplugin (calendar_ics/recur/store).
--
-- Times are "wall seconds": local wall-clock time counted from 1970-01-01 as if it were UTC, so a
-- day is always 86400 and the date of t is t // 86400. ICS times with Z are moved by the device's
-- UTC offset; times with a TZID are taken as they are written (right when the calendar's zone is
-- the reader's). Numbers may be 32-bit on the device, so nothing goes past 2037.
--
-- calendars.txt: one calendar a line, "Name|address|on" (or just the address; "off" hides it).
-- c<hash>.txt:   a calendar's cache, "#cal<TAB>updated<TAB>offset<TAB>bytes" then one event a line,
--                start, end, all-day, RRULE, EXDATEs, UID, title, place, notes (tab-separated).

local C = {}

C.MAXT = 2145916799                 -- 2037-12-31 23:59:59
local DAY = 86400
local KEEP_BACK, KEEP_AHEAD = 62 * DAY, 400 * DAY
local MAX_EVENTS = 600

C.WDAY = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' }
C.WDAY_LONG = { 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' }
C.MON = { 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' }
C.MONTH = { 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
            'October', 'November', 'December' }

------------------------------------------------------------------ dates

-- days since 1970-01-01 (H. Hinnant's civil algorithms; // floors, as they need)
function C.days(y, m, d)
  if m <= 2 then y = y - 1 end
  local era = y // 400
  local yoe = y - era * 400
  local doy = (153 * (m + (m > 2 and -3 or 9)) + 2) // 5 + d - 1
  return era * 146097 + yoe * 365 + yoe // 4 - yoe // 100 + doy - 719468
end
function C.civil(z)
  z = z + 719468
  local era = z // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp < 10 and mp + 3 or mp - 9
  return yoe + era * 400 + (m <= 2 and 1 or 0), m, d
end
function C.month_len(y, m)
  if m == 12 then return 31 end
  return C.days(y, m + 1, 1) - C.days(y, m, 1)
end
function C.ts(y, m, d, h, mi, s)
  if y > 2037 then return C.MAXT end
  return C.days(y, m, d) * DAY + (h or 0) * 3600 + (mi or 0) * 60 + (s or 0)
end
function C.wday(day) return (day + 4) % 7 end            -- 0 = Sunday

-- the clock: UTC seconds and the UTC offset (from the wall hour the device reports)
function C.clock()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not ok or type(t) ~= 'table' or not tonumber(t.epoch_sec) then return 0, 0 end
  local e = math.floor(tonumber(t.epoch_sec))
  local h = tonumber(t.hour)
  if not h then
    local l = tonumber(t.local_sec)                -- the local time as seconds since 1970
    if l and math.abs(l - e) <= 14 * 3600 then return e, ((math.floor(l) - e + 450) // 900) * 900 end
    return e, 0
  end
  local off = math.floor(h) * 3600 + math.floor(tonumber(t.minute) or 0) * 60 + math.floor(tonumber(t.second) or 0) - e % DAY
  if off > 14 * 3600 then off = off - DAY elseif off < -12 * 3600 then off = off + DAY end
  return e, ((off + 450) // 900) * 900
end

function C.hm(t)
  local s = t % DAY
  return string.format('%02d:%02d', s // 3600, s % 3600 // 60)
end
-- "Tue 27 Oct" / "Tuesday 27 October 2026"
function C.date(day, long)
  local y, m, d = C.civil(day)
  if long then return C.WDAY_LONG[C.wday(day) + 1] .. ' ' .. d .. ' ' .. C.MONTH[m] .. ' ' .. y end
  return C.WDAY[C.wday(day) + 1] .. ' ' .. d .. ' ' .. C.MON[m]
end
-- when an event happens, in words
function C.when(it)
  local d0 = it.s // DAY
  if it.ad then
    local last = (it.e - 1) // DAY
    if last <= d0 then return C.date(d0) .. ', all day' end
    return C.date(d0) .. ' - ' .. C.date(last) .. ', all day'
  end
  local d1 = it.e // DAY
  if it.e == it.s then return C.date(d0) .. ', ' .. C.hm(it.s) end
  if d1 == d0 or (d1 == d0 + 1 and it.e % DAY == 0) then return C.date(d0) .. ', ' .. C.hm(it.s) .. ' - ' .. C.hm(it.e) end
  return C.date(d0) .. ' ' .. C.hm(it.s) .. ' - ' .. C.date(d1) .. ' ' .. C.hm(it.e)
end

------------------------------------------------------------------ text

function C.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 10
end
local function drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
-- s cut with an ellipsis to fit maxw
function C.fit(f, s, maxw)
  s = tostring(s or '')
  if C.width(f, s) <= maxw then return s end
  local t = s:sub(1, math.max(1, maxw // 4))
  while #t > 0 and not utf8.len(t) do t = t:sub(1, -2) end      -- not inside a letter
  while #t > 0 and C.width(f, t .. '…') > maxw do t = drop_last(t) end
  return t .. '…'
end
-- word wrap (ASCII spaces only); a word wider than the line is broken
function C.wrap(f, s, maxw)
  local out = {}
  for para in (tostring(s or '') .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if C.width(f, cand) <= maxw then
        line = cand
      else
        if line ~= '' then out[#out + 1] = line end
        local w = word
        while C.width(f, w) > maxw do
          local cut = w
          while #cut > 1 and C.width(f, cut) > maxw do cut = drop_last(cut) end
          out[#out + 1] = cut
          w = w:sub(#cut + 1)
        end
        line = w
      end
    end
    out[#out + 1] = line
  end
  return out
end
local function cut(s, n)
  if #s <= n then return s end
  return drop_last(s:sub(1, n)) .. '…'
end

------------------------------------------------------------------ the calendar list

-- a short name for a cache file: two Adler-style sums (stays far below 2^31)
function C.hash(s)
  local a, b = 1, 0
  for k = 1, #s do a = (a + s:byte(k)) % 65521; b = (b + a) % 65521 end
  return string.format('%04x%04x', b, a)
end
function C.cache_name(url) return 'c' .. C.hash(url) .. '.txt' end

function C.fix_url(u)
  u = u:gsub('^[ \t]+', ''):gsub('[ \t\r]+$', '')
  return (u:gsub('^webcals?://', 'https://'))
end

------------------------------------------------------------------ fetching

local UA = 'XteinkLicoriceCalendar/1.0 (https://github.com/omer-faruq/touch-licorice-apps)'

function C.enc(s)
  return (s:gsub('[^A-Za-z0-9%-%._~]', function(ch) return string.format('%%%02X', ch:byte()) end))
end
-- the request for a calendar: straight to its address, or through the rss-opds Worker
-- (wk.host = 'name.workers.dev', wk.auth = 'user:password'; /api/ics sends only the events near
-- today). gz asks for the file compressed: Google's iCal file holds a calendar's whole history,
-- and the reader takes in only so much of an answer (gzip makes it about a quarter).
function C.request(url, wk, gz)
  local host = wk and (wk.host or ''):gsub('^%a+://', ''):gsub('/+$', '') or ''
  local headers = { ['User-Agent'] = UA, ['Accept'] = 'text/calendar, */*' }
  if gz then headers['Accept-Encoding'] = 'gzip' end
  if host == '' then return { url = url, method = 'GET', timeout_ms = 45000, headers = headers } end
  if wk.auth and wk.auth ~= '' then
    local ok, b64 = pcall(function() return ctx.base64:encode(wk.auth) end)
    if ok and type(b64) == 'string' then headers['Authorization'] = 'Basic ' .. b64 end
  end
  return { url = 'https://' .. host .. '/api/ics?url=' .. C.enc(url), method = 'GET', timeout_ms = 45000, headers = headers }, true
end

-- where a sync is, in sync_step.txt: when the reader closes the app mid-way (out of memory
-- closes it without a Lua error), the next start knows the step
function C.step(s) pcall(function() ctx.storage:write('sync_step.txt', s) end) end
-- give memory back now (the host has no collectgarbage; ctx.gc's calls are not documented)
function C.free()
  for _k, f in ipairs({ function() ctx.gc:collect() end, function() ctx.gc:full() end, function() ctx.gc.collect() end }) do
    if pcall(f) then return end
  end
end

-- gzip -> text with the firmware's zlib (which call it takes is not documented: each is tried)
function C.gunzip(b, log)
  local z = ctx.zlib
  if not z then return nil end
  local tries = {
    function() return z:decompress(b) end,
    function() return z:decompress(b, 'gzip') end,
    function() return z:decompress(b, { format = 'gzip' }) end,
    function() return z:decompress(b, { gzip = true }) end,
    function() return z:gunzip(b) end,
    function() return z:inflate(b) end,
  }
  for k, f in ipairs(tries) do
    if log then C.step('unpack ' .. k .. ', ' .. (#b // 1024) .. ' KB packed') end
    local ok, out = pcall(f)
    if ok and type(out) == 'string' and out:find('BEGIN:VCALENDAR', 1, true) then return out end
  end
  return nil
end

-- does the firmware's zlib unpack gzip at all (a tiny calendar, packed)
local SAMPLE = '\31\139\8\0\0\0\0\0\2\10\115\114\117\247\244\179\10\115\118\244\113\245\115\113\12\226\229\2\82\200\92\0\242\161\89\152\32\0\0\0'
local gz_ok = nil
function C.gunzip_works()
  if gz_ok == nil then gz_ok = C.gunzip(SAMPLE) ~= nil end
  return gz_ok
end

-- the answer -> the calendar text, or nil, why and what went wrong ('gzip': it came compressed
-- and could not be unpacked; 'cut': it ended early). A cut-off file is never used: events would
-- be missing at random, as Google sends them in a different order each time.
function C.answer(resp, via, log)
  if type(resp) ~= 'table' or type(resp.body) ~= 'string' then return nil, 'no answer' end
  local body = resp.body
  resp.body = nil                                -- one copy less while it is unpacked and read
  local code = tonumber(resp.status) or tonumber(resp.code)
  if code and code >= 400 then
    if via and code == 401 then return nil, 'Worker login is wrong' end
    if via and code == 404 then return nil, 'the Worker has no /api/ics yet: update it' end
    local why = body:match('"error"%s*:%s*"([^"]*)"')
    return nil, why or ('HTTP ' .. code)
  end
  local packed = 0
  if body:sub(1, 2) == '\31\139' then
    packed = #body
    C.free()
    local text = C.gunzip(body, log)
    if not text then
      if C.gunzip_works() then                   -- it unpacks, so this answer ended early
        return nil, 'cut off after ' .. (#body // 1024) .. ' KB packed' .. (via and '' or ': try the Worker (Settings)'), 'cut'
      end
      return nil, 'could not unpack', 'gzip'
    end
    body, text = text, nil
    C.free()
  end
  if not body:find('BEGIN:VCALENDAR', 1, true) then return nil, 'not an iCal address' end
  if not body:find('END:VCALENDAR', 1, true) then
    return nil, 'cut off after ' .. ((packed > 0 and packed or #body) // 1024) .. ' KB' .. (via and '' or ': try the Worker (Settings)'), 'cut'
  end
  return body, nil, nil, packed
end

function C.parse_list(text)
  local out = {}
  for ln in (text or ''):gmatch('[^\n]+') do
    local l = ln:gsub('\r', ''):gsub('^[ \t]+', '')
    if l ~= '' and l:sub(1, 1) ~= '#' then
      local parts = {}
      for p in (l .. '|'):gmatch('([^|]*)|') do parts[#parts + 1] = p end
      local name, url, on
      if parts[1]:match('^%a+://') then url, on = parts[1], parts[2] else name, url, on = parts[1], parts[2], parts[3] end
      if url and url:match('^%a+://') then
        url = C.fix_url(url)
        if not name or not name:match('%S') then name = url:match('^https?://([^/]+)') or 'Calendar' end
        out[#out + 1] = { name = (name:gsub('^[ \t]+', ''):gsub('[ \t]+$', '')), url = url,
                          on = not (on and on:lower():match('^%s*off')) }
      end
    end
  end
  return out
end
function C.list_text(list)
  local out = { '# Calendar: one calendar a line, Name|address|on (or off). The address is the',
                '# calendar\'s secret iCal address (Google: Settings > the calendar > Integrate calendar).' }
  for _k, c in ipairs(list) do out[#out + 1] = c.name:gsub('|', '/') .. '|' .. c.url .. '|' .. (c.on and 'on' or 'off') end
  return table.concat(out, '\n') .. '\n'
end

------------------------------------------------------------------ reading iCalendar

-- "20261027" (all day), "20261027T090000" (wall), "20261027T060000Z" (UTC, moved by off)
function C.parse_dt(v, off)
  local y, m, d, rest = v:match('^(%d%d%d%d)(%d%d)(%d%d)(.*)$')
  if not y then return nil end
  y, m, d = tonumber(y), tonumber(m), tonumber(d)
  local H, M, S, z = rest:match('^T(%d%d)(%d%d)(%d%d)(Z?)')
  if not H then return C.ts(y, m, d), true end
  local t = C.ts(y, m, d, tonumber(H), tonumber(M), tonumber(S))
  if z == 'Z' and t < C.MAXT then t = t + (off or 0) end
  return t, false
end
-- "PT1H30M", "P2D", "-P1W" -> seconds
function C.parse_dur(v)
  local sign, body = v:match('^([+%-]?)P(.*)$')
  if not body then return nil end
  local dp, tp = body:match('^([^T]*)T?(.*)$')
  local s = 0
  local w = dp:match('(%d+)W'); if w then s = s + tonumber(w) * 7 * DAY end
  local d = dp:match('(%d+)D'); if d then s = s + tonumber(d) * DAY end
  local h = tp:match('(%d+)H'); if h then s = s + tonumber(h) * 3600 end
  local mi = tp:match('(%d+)M'); if mi then s = s + tonumber(mi) * 60 end
  local se = tp:match('(%d+)S'); if se then s = s + tonumber(se) end
  return sign == '-' and -s or s
end

local ENT = { nbsp = ' ', lt = '<', gt = '>', quot = '"', amp = '&', apos = "'", ['#39'] = "'" }
local function text_value(v, max)
  v = v:gsub('\\([nN,;\\])', function(c) if c == 'n' or c == 'N' then return '\n' end return c end)
  if v:find('<', 1, true) then              -- Google sends some notes as HTML
    v = v:gsub('<[Bb][Rr][^>]*>', '\n'):gsub('</?[Pp][^>]*>', '\n'):gsub('</?[Ll][Ii][^>]*>', '\n'):gsub('<[^>]*>', '')
    v = v:gsub('&(#?%w+);', function(e) return ENT[e] end)
  end
  v = v:gsub('\r', ''):gsub('[ \t]+\n', '\n'):gsub('\n\n\n+', '\n\n'):gsub('^[ \t\n]+', ''):gsub('[ \t\n]+$', '')
  return cut(v, max)
end

-- the property name, its parameters and the value (a ':' inside a quoted parameter is skipped)
local function split_prop(l)
  local name, rest = l:match('^([%w%-]+)(.*)$')
  if not name then return nil end
  local c = rest:find(':', 1, true)
  if not c then return nil end
  local q = rest:find('"', 1, true)
  if q and q < c then
    local inq = false
    c = nil
    for k = 1, #rest do
      local ch = rest:byte(k)
      if ch == 34 then inq = not inq elseif ch == 58 and not inq then c = k; break end
    end
    if not c then return nil end
  end
  return name:upper(), rest:sub(1, c - 1), rest:sub(c + 1)
end

local WD = { SU = 0, MO = 1, TU = 2, WE = 3, TH = 4, FR = 5, SA = 6 }
-- an RRULE's parts; `till` is its UNTIL in wall seconds
function C.rule(rr, off)
  local r = { freq = 'DAILY', interval = 1 }
  for k, v in rr:gmatch('([^=;]+)=([^;]*)') do
    local key = k:upper()
    if key == 'FREQ' then r.freq = v:upper()
    elseif key == 'INTERVAL' then r.interval = math.max(1, tonumber(v) or 1)
    elseif key == 'COUNT' then r.count = tonumber(v)
    elseif key == 'UNTIL' then
      local t, ad = C.parse_dt(v, off)
      if t then r.till = ad and t + DAY - 1 or t end
    elseif key == 'BYDAY' then
      r.byday = {}
      for part in v:gmatch('[^,]+') do
        local n, wd = part:upper():match('^([+%-]?%d*)(%a%a)$')
        if wd and WD[wd] then r.byday[#r.byday + 1] = { n = tonumber(n), wd = WD[wd] } end
      end
    elseif key == 'BYMONTHDAY' then
      r.bymd = {}
      for part in v:gmatch('[^,]+') do if tonumber(part) then r.bymd[#r.bymd + 1] = tonumber(part) end end
    elseif key == 'BYMONTH' then
      r.bymonth = {}
      for part in v:gmatch('[^,]+') do if tonumber(part) then r.bymonth[tonumber(part)] = true end end
    end
  end
  return r
end

-- iCalendar text -> events near `today` (a day number): those within two months back and
-- 400 days ahead, and every repeating one that has not ended. Notes are cut to keep memory low.
function C.parse_ics(body, off, today)
  local w0, w1 = today * DAY - KEEP_BACK, today * DAY + KEEP_AHEAD
  local events, moved = {}, {}
  local cur, depth = nil, 0

  local function finish(ev)
    if not ev.s then return end
    if not ev.e then ev.e = ev.dur and ev.s + ev.dur or (ev.ad and ev.s + DAY or ev.s) end
    if ev.e < ev.s then ev.e = ev.s end
    if ev.rid then
      ev.rr = nil                               -- one changed (or cancelled) instance of a series
      if ev.uid then
        local l = moved[ev.uid] or {}
        l[#l + 1] = ev.rid
        moved[ev.uid] = l
      end
    end
    if ev.cancel then return end
    if ev.rr then
      local r = C.rule(ev.rr, off)
      if r.till and r.till < w0 then return end
    elseif ev.e < w0 or ev.s > w1 then
      return
    end
    events[#events + 1] = ev
  end

  local function prop(l)
    local name, params, v = split_prop(l)
    if not name then return end
    if name == 'BEGIN' then
      if v == 'VEVENT' then cur, depth = { ex = {}, sum = '' }, 0 elseif cur then depth = depth + 1 end
    elseif name == 'END' then
      if v == 'VEVENT' then
        if cur then finish(cur) end
        cur = nil
      elseif cur and depth > 0 then depth = depth - 1 end
    elseif cur and depth == 0 then           -- an alarm's own SUMMARY must not replace the title
      if name == 'SUMMARY' then cur.sum = text_value(v, 120)
      elseif name == 'DTSTART' then cur.s, cur.ad = C.parse_dt(v, off)
      elseif name == 'DTEND' then cur.e = C.parse_dt(v, off)
      elseif name == 'DURATION' then cur.dur = C.parse_dur(v)
      elseif name == 'LOCATION' then cur.loc = text_value(v, 100)
      elseif name == 'DESCRIPTION' then cur.desc = text_value(v, 400)
      elseif name == 'UID' then cur.uid = v:sub(1, 80)
      elseif name == 'RRULE' then cur.rr = v
      elseif name == 'RECURRENCE-ID' then cur.rid = C.parse_dt(v, off)
      elseif name == 'STATUS' then cur.cancel = v:upper() == 'CANCELLED'
      elseif name == 'EXDATE' then
        for part in v:gmatch('[^,]+') do
          local t = C.parse_dt(part, off)
          if t then cur.ex[#cur.ex + 1] = t end
        end
      end
    end
  end

  -- unfold as we go: a line starting with a space or tab continues the one before
  local pos, n, held = 1, #body, nil
  while pos <= n do
    local e = body:find('\n', pos, true) or n + 1
    local l = body:sub(pos, e - 1)
    if l:byte(-1) == 13 then l = l:sub(1, -2) end
    local c1 = l:byte(1)
    if (c1 == 32 or c1 == 9) and held then
      if #held < 3000 then held = held .. l:sub(2) end
    else
      if held then prop(held) end
      held = l
    end
    pos = e + 1
  end
  if held then prop(held) end

  for _k, ev in ipairs(events) do
    local m = ev.rr and ev.uid and moved[ev.uid]
    if m then for _j, t in ipairs(m) do ev.ex[#ev.ex + 1] = t end end
  end
  -- far too many: keep the repeating ones and those nearest today
  if #events > MAX_EVENTS then
    local now = today * DAY
    table.sort(events, function(a, b)
      local da = a.rr and -1 or math.abs(a.s - now)
      local db = b.rr and -1 or math.abs(b.s - now)
      return da < db
    end)
    for k = #events, MAX_EVENTS + 1, -1 do events[k] = nil end
  end
  return events
end

------------------------------------------------------------------ the cache

local ESC = { ['\\'] = '\\\\', ['\t'] = '\\t', ['\n'] = '\\n' }
local UNESC = { t = '\t', n = '\n', ['\\'] = '\\' }
local function esc(s) return (tostring(s or ''):gsub('[\\\t\n]', ESC)) end
local function unesc(s) return (s:gsub('\\(.)', UNESC)) end
local function fields(l)
  local out, pos = {}, 1
  while true do
    local i = l:find('\t', pos, true)
    if not i then out[#out + 1] = l:sub(pos); return out end
    out[#out + 1] = l:sub(pos, i - 1)
    pos = i + 1
  end
end

function C.cache_text(events, updated, off, bytes, packed)
  local out = { '#cal\t' .. updated .. '\t' .. off .. '\t' .. (bytes or 0) .. '\t' .. (packed or 0) }
  for _k, ev in ipairs(events) do
    out[#out + 1] = table.concat({ ev.s, ev.e, ev.ad and 1 or 0, esc(ev.rr), table.concat(ev.ex or {}, ','),
                                   esc(ev.uid), esc(ev.sum), esc(ev.loc), esc(ev.desc) }, '\t')
  end
  return table.concat(out, '\n')
end
-- -> events, updated (UTC seconds), bytes, packed bytes (0: not gzip); nil when there is no cache
function C.load_cache(text)
  if not text or text:sub(1, 4) ~= '#cal' then return nil end
  local events, updated, bytes, packed = {}, 0, 0, 0
  for l in text:gmatch('[^\n]+') do
    local f = fields(l)
    if f[1] == '#cal' then
      updated, bytes, packed = tonumber(f[2]) or 0, tonumber(f[4]) or 0, tonumber(f[5]) or 0
    elseif #f >= 9 and tonumber(f[1]) then
      local ex = {}
      for t in f[5]:gmatch('[^,]+') do ex[#ex + 1] = tonumber(t) end
      local d = unesc(f[9])
      events[#events + 1] = { s = tonumber(f[1]), e = tonumber(f[2]), ad = f[3] == '1', rr = f[4] ~= '' and unesc(f[4]) or nil,
                              ex = ex, uid = f[6] ~= '' and unesc(f[6]) or nil, sum = unesc(f[7]),
                              loc = f[8] ~= '' and unesc(f[8]) or nil, desc = d ~= '' and d or nil }
    end
  end
  return events, updated, bytes, packed
end

------------------------------------------------------------------ recurrence

local MAX_PERIODS = 3000

local function overlaps(s, e, w0, w1) return s < w1 and (e > w0 or (e == s and s >= w0)) end
local function instance(ev, s, e, cal)
  return { s = s, e = e, ad = ev.ad, sum = ev.sum, loc = ev.loc, desc = ev.desc, uid = ev.uid, cal = cal }
end

-- the days of a month that a MONTHLY/YEARLY rule picks
local function month_days(r, y, m, d0)
  local len = C.month_len(y, m)
  local first = C.days(y, m, 1)
  local out = {}
  if r.bymd then
    for _k, md in ipairs(r.bymd) do
      local d = md > 0 and md or len + md + 1
      if d >= 1 and d <= len then out[#out + 1] = first + d - 1 end
    end
  elseif r.byday then
    for _k, b in ipairs(r.byday) do
      local f = first + (b.wd - C.wday(first)) % 7            -- the first such weekday
      if b.n and b.n > 0 then
        local d = f + (b.n - 1) * 7
        if d < first + len then out[#out + 1] = d end
      elseif b.n and b.n < 0 then
        local last = f + ((first + len - 1 - f) // 7) * 7
        local d = last + (b.n + 1) * 7
        if d >= first then out[#out + 1] = d end
      else
        local d = f
        while d < first + len do out[#out + 1] = d; d = d + 7 end
      end
    end
  elseif d0 <= len then
    out[1] = first + d0 - 1
  end
  table.sort(out)
  return out
end

-- every instance of `ev` that overlaps [w0, w1), appended to out
function C.expand(ev, w0, w1, out, cal, off)
  if not ev.rr then
    if overlaps(ev.s, ev.e, w0, w1) then out[#out + 1] = instance(ev, ev.s, ev.e, cal) end
    return
  end
  local r = ev.rule
  if not r then r = C.rule(ev.rr, off); ev.rule = r end
  local ex = ev.exset
  if not ex then
    ex = {}
    for _k, t in ipairs(ev.ex or {}) do ex[t] = true end
    ev.exset = ex
  end
  local dur = ev.e - ev.s
  local sd, tod = ev.s // DAY, ev.s % DAY
  local y0, m0, d0 = C.civil(sd)
  local count, done = 0, false
  local wd0 = w0 // DAY

  local function take(day)
    local t = day * DAY + tod
    if t < ev.s then return end
    if (r.till and t > r.till) or t >= w1 or t > C.MAXT - dur then done = true; return end
    count = count + 1
    if not ex[t] and overlaps(t, t + dur, w0, w1) then out[#out + 1] = instance(ev, t, t + dur, cal) end
    if r.count and count >= r.count then done = true end
  end
  local function month_ok(day)
    if not r.bymonth then return true end
    local _y, m = C.civil(day)
    return r.bymonth[m] == true
  end
  local function wday_ok(day)
    if not r.byday then return true end
    local w = C.wday(day)
    for _k, b in ipairs(r.byday) do if b.wd == w then return true end end
    return false
  end

  if r.freq == 'DAILY' then
    local step, p = r.interval, sd
    if not r.count and p < wd0 - 1 then p = p + ((wd0 - 1 - p) // step) * step end
    for _i = 1, MAX_PERIODS * 4 do
      if p * DAY + tod >= w1 then break end
      if month_ok(p) and wday_ok(p) then take(p) end
      if done then break end
      p = p + step
    end
  elseif r.freq == 'WEEKLY' then
    local step = 7 * r.interval
    local ws = sd - (C.wday(sd) + 6) % 7                       -- the Monday of the first week
    local offs = {}
    if r.byday then
      for _k, b in ipairs(r.byday) do offs[#offs + 1] = (b.wd + 6) % 7 end
      table.sort(offs)
    else
      offs[1] = (C.wday(sd) + 6) % 7
    end
    if not r.count and ws < wd0 - 7 then ws = ws + ((wd0 - 7 - ws) // step) * step end
    for _i = 1, MAX_PERIODS do
      if ws * DAY >= w1 then break end
      for _k, o in ipairs(offs) do
        if month_ok(ws + o) then take(ws + o) end
        if done then break end
      end
      if done then break end
      ws = ws + step
    end
  elseif r.freq == 'MONTHLY' or r.freq == 'YEARLY' then
    local yearly = r.freq == 'YEARLY'
    local mi = y0 * 12 + (m0 - 1)                               -- months counted from year 0
    local step = yearly and 12 * r.interval or r.interval
    if not r.count then
      local wy, wm = C.civil(wd0)
      local target = wy * 12 + wm - 1 - 12
      if mi < target then mi = mi + ((target - mi) // step) * step end
    end
    for _i = 1, MAX_PERIODS do
      local y, m = mi // 12, mi % 12 + 1
      if C.days(y, m, 1) * DAY >= w1 or y > 2037 then break end
      if yearly then
        local months = {}
        if r.bymonth then for k = 1, 12 do if r.bymonth[k] then months[#months + 1] = k end end else months[1] = m0 end
        for _k, mm in ipairs(months) do
          for _j, d in ipairs(month_days(r, y, mm, d0)) do take(d); if done then break end end
          if done then break end
        end
      elseif month_ok(C.days(y, m, 1)) then
        for _j, d in ipairs(month_days(r, y, m, d0)) do take(d); if done then break end end
      end
      if done then break end
      mi = mi + step
    end
  else
    if overlaps(ev.s, ev.e, w0, w1) then out[#out + 1] = instance(ev, ev.s, ev.e, cal) end
  end
end

-- the instances of every calendar shown in [w0, w1), sorted (all-day first on a day), one per
-- UID and start (an event shared between two calendars shows once)
function C.between(cals, w0, w1, off)
  local out, seen, list = {}, {}, {}
  for _k, cal in ipairs(cals) do
    if cal.on and cal.events then
      for _j, ev in ipairs(cal.events) do C.expand(ev, w0, w1, list, cal, off) end
    end
  end
  for _k, it in ipairs(list) do
    local key = it.uid and (it.uid .. '@' .. it.s)
    if not key or not seen[key] then
      if key then seen[key] = true end
      out[#out + 1] = it
    end
  end
  table.sort(out, function(a, b)
    local da, db = a.s // DAY, b.s // DAY
    if da ~= db then return da < db end
    if a.ad ~= b.ad then return a.ad == true end
    if a.s ~= b.s then return a.s < b.s end
    return (a.sum or '') < (b.sum or '')
  end)
  return out
end

-- does an instance show on `day`
function C.on_day(it, day)
  local d0, d1 = day * DAY, (day + 1) * DAY
  return it.s < d1 and (it.e > d0 or (it.e == it.s and it.s >= d0))
end
-- instances by day: { [day] = { it, ... } } for days in [first, first + n)
function C.by_day(insts, first, n)
  local t = {}
  for _k, it in ipairs(insts) do
    local a = math.max(first, it.s // DAY)
    local b = math.min(first + n - 1, (it.e > it.s and (it.e - 1) or it.e) // DAY)
    for d = a, b do
      local l = t[d]
      if not l then l = {}; t[d] = l end
      l[#l + 1] = it
    end
  end
  return t
end

return C
end

__mods['views'] = function()
-- Calendar views for a 480 px wide screen, shared by the app and the lock screen: a month grid,
-- a week of day rows, a day's timeline and an agenda list. Each draws into a box and returns the
-- places a tap can land on ({ x, y, w, h, day = } or { ..., it = }). `env` carries
--   font(name), lh(name), today (day number), now (wall seconds), ws (0 Sunday, 1 Monday first)
-- and insts (C.between for the view's window, see V.window).
-- Lines and frames only: large black areas ghost on e-ink. The host draws ~1024 commands a screen.

local C = require('cal')
local V = {}
local DAY = 86400

-- the days a view covers: first day, number of days
function V.window(mode, day, ws)
  if mode == 'month' then
    local y, m = C.civil(day)
    local first = C.days(y, m, 1)
    local lead = (C.wday(first) - ws) % 7
    return first - lead, 42
  elseif mode == 'week' then
    return day - (C.wday(day) - ws) % 7, 7
  elseif mode == 'agenda' then
    return day, 60
  end
  return day, 1
end

function V.title(mode, day, ws)
  local y, m, d = C.civil(day)
  if mode == 'month' then return C.MONTH[m] .. ' ' .. y end
  if mode == 'week' then
    local a = V.window('week', day, ws)
    local y1, m1, d1 = C.civil(a)
    local y2, m2, d2 = C.civil(a + 6)
    if m1 == m2 then return d1 .. ' - ' .. d2 .. ' ' .. C.MON[m2] .. ' ' .. y2 end
    return d1 .. ' ' .. C.MON[m1] .. (y1 ~= y2 and (' ' .. y1) or '') .. ' - ' .. d2 .. ' ' .. C.MON[m2] .. ' ' .. y2
  end
  if mode == 'agenda' then return 'From ' .. C.date(day) .. ' ' .. y end
  return C.WDAY_LONG[C.wday(day) + 1] .. ' ' .. d .. ' ' .. C.MONTH[m] .. ' ' .. y
end

local function text(gg, x, y, s, f) gg:text(x, y, s, { font = f }) end

------------------------------------------------------------------ month

function V.month(gg, env, day, x, y, w, h)
  local hits = {}
  local yy, mm = C.civil(day)
  local first = C.days(yy, mm, 1)
  local len = C.month_len(yy, mm)
  local g0 = V.window('month', day, env.ws)
  local rows = (first - g0 + len + 6) // 7
  local cw = w // 7
  local fs, fm = env.font('small'), env.font('medium')
  local lh = env.lh('small')
  for k = 0, 6 do
    local s = C.WDAY[(env.ws + k) % 7 + 1]:sub(1, 2)
    text(gg, x + k * cw + (cw - C.width(fs, s)) // 2, y, s, fs)
  end
  local top = y + lh + 4
  local ch = (h - lh - 4) // rows
  for r = 0, rows do gg:line(x, top + r * ch, x + 7 * cw, top + r * ch) end
  for k = 0, 7 do gg:line(x + k * cw, top, x + k * cw, top + rows * ch) end
  local by = C.by_day(env.insts, g0, rows * 7)
  local maxl = (ch - 28) // lh
  for i = 0, rows * 7 - 1 do
    local d = g0 + i
    local cx, cy = x + (i % 7) * cw, top + (i // 7) * ch
    local _y, _m, dn = C.civil(d)
    local inside = d >= first and d < first + len
    text(gg, cx + 5, cy + 3, tostring(dn), inside and fm or fs)
    if d == env.today then
      gg:rect(cx + 2, cy + 2, cw - 3, ch - 3, { line_width = 3 })
    end
    local list = by[d] or {}
    local ly = cy + 28
    for k, it in ipairs(list) do
      if k > maxl then break end
      if k == maxl and #list > maxl then
        text(gg, cx + 4, ly, '+' .. (#list - k + 1), fs)
        break
      end
      text(gg, cx + 4, ly, C.fit(fs, it.sum, cw - 7), fs)
      ly = ly + lh
    end
    hits[#hits + 1] = { x = cx, y = cy, w = cw, h = ch, day = d }
  end
  return hits
end

------------------------------------------------------------------ week

local function short_line(it, day)
  if it.ad or it.s < day * DAY then return it.sum end
  return C.hm(it.s) .. ' ' .. it.sum
end

function V.week(gg, env, day, x, y, w, h)
  local hits = {}
  local start = V.window('week', day, env.ws)
  local rh = h // 7
  local fs, fm, fl = env.font('small'), env.font('medium'), env.font('large')
  local lm = env.lh('medium')
  local by = C.by_day(env.insts, start, 7)
  local lw = 70
  for k = 0, 6 do
    local d = start + k
    local ry = y + k * rh
    local _y, m, dn = C.civil(d)
    text(gg, x + 6, ry + 6, C.WDAY[C.wday(d) + 1], fs)
    text(gg, x + 6, ry + 28, tostring(dn), fl)
    if dn == 1 or k == 0 then text(gg, x + 6 + C.width(fl, tostring(dn)) + 4, ry + 36, C.MON[m], fs) end
    if d == env.today then
      gg:rect(x + 1, ry + 2, w - 2, rh - 3, { line_width = 3 })
    end
    if k > 0 then gg:line(x, ry, x + w, ry) end
    local list = by[d] or {}
    local maxl = math.max(1, (rh - 8) // lm)
    local ly = ry + 5
    for j, it in ipairs(list) do
      if j > maxl then break end
      local s = short_line(it, d)
      if j == maxl and #list > maxl then s = '+' .. (#list - j + 1) .. ' more' end
      text(gg, x + lw + 6, ly, C.fit(fm, s, w - lw - 14), fm)
      ly = ly + lm
    end
    hits[#hits + 1] = { x = x, y = ry, w = w, h = rh, day = d }
  end
  return hits
end

------------------------------------------------------------------ day

-- opts.from: start at that hour and show as many hours of opts.ph px as fit, past midnight into the
-- next day (the lock screen: "from now on"; env.insts must then cover two days)
function V.day(gg, env, day, x, y, w, h, opts)
  opts = opts or {}
  local hits = {}
  local fs, fm = env.font('small'), env.font('medium')
  local ls, lm = env.lh('small'), env.lh('medium')
  local base = day * DAY
  local allday, timed, earlier = {}, {}, {}
  for _k, it in ipairs(env.insts) do
    local whole = it.ad or (it.s <= base and it.e >= base + DAY)
    if whole then
      if C.on_day(it, day) then allday[#allday + 1] = it end
    elseif opts.from then
      local from = base + opts.from * 3600
      if it.s < base + 48 * 3600 and (it.e > from or (it.e == it.s and it.s >= from)) then
        timed[#timed + 1] = it
      elseif it.s >= base and it.s < from then
        earlier[#earlier + 1] = it                 -- over already: one line above the hours
      end
    elseif C.on_day(it, day) then
      timed[#timed + 1] = it
    end
  end
  -- all-day events on top
  local ty = y
  for k, ev in ipairs(allday) do
    if k > 3 then
      text(gg, x + 8, ty, '+' .. (#allday - 3) .. ' more all day', fs)
      ty = ty + ls + 2
      break
    end
    gg:rect(x + 4, ty, w - 8, lm + 6)
    text(gg, x + 10, ty + 3, C.fit(fm, ev.sum, w - 24), fm)
    hits[#hits + 1] = { x = x + 4, y = ty, w = w - 8, h = lm + 6, it = ev }
    ty = ty + lm + 10
  end
  if #earlier > 0 then
    local parts = {}
    for _k, it in ipairs(earlier) do parts[#parts + 1] = C.hm(it.s) .. ' ' .. it.sum end
    text(gg, x + 6, ty, C.fit(fs, 'Earlier: ' .. table.concat(parts, ', '), w - 12), fs)
    ty = ty + ls + 4
  end
  local top = ty + 4
  local h0, h1, ph
  local later = {}                      -- today's events that start below the last hour shown
  if opts.from then
    ph = opts.ph or 52
    h0 = opts.from
    local room = y + h - top - 4
    h1 = h0 + math.max(1, room // ph)
    local function hidden()
      later = {}
      for _k, it in ipairs(timed) do
        if it.s >= base + h1 * 3600 and it.s < base + DAY then later[#later + 1] = it end
      end
    end
    hidden()
    -- they get a line at the bottom: give up an hour for it when the hours fill the box
    if #later > 0 and room - (h1 - h0) * ph < ls + 8 and h1 - h0 > 1 then
      h1 = h1 - 1
      hidden()
    end
  else
    -- the hours: 7 to 21, widened to the day's events
    h0, h1 = 7, 21
    for _k, it in ipairs(timed) do
      local a = math.max(0, (it.s - base) // 3600)
      local b = math.min(24, (math.min(it.e, base + DAY) - base + 3599) // 3600)
      if a < h0 then h0 = a end
      if b > h1 then h1 = b end
    end
    ph = (y + h - top - 4) // (h1 - h0)
  end
  local gx = x + 50
  for hr = h0, h1 do
    local ly = top + (hr - h0) * ph
    gg:line(gx - 4, ly, x + w, ly)
    if hr == 24 and hr > h0 then
      gg:line(gx - 4, ly + 1, x + w, ly + 1)
      text(gg, gx + 4, ly + 3, C.date(day + 1), fs)
    end
    if hr < h1 then text(gg, x + 6, ly + 2, string.format('%02d', hr % 24), fs) end
  end
  local function ypos(t)
    local s = math.max(h0 * 3600, math.min(t - base, h1 * 3600)) - h0 * 3600
    return top + s * ph // 3600
  end
  if opts.from then                     -- only what shows between the first and last hour
    local keep = {}
    for _k, it in ipairs(timed) do if it.s < base + h1 * 3600 then keep[#keep + 1] = it end end
    timed = keep
  end
  -- side by side when they overlap: greedy columns inside each group of overlapping events
  local i = 1
  while i <= #timed do
    local group, ends, j = {}, timed[i].e, i
    while j <= #timed and (j == i or timed[j].s < ends) do
      group[#group + 1] = timed[j]
      if timed[j].e > ends then ends = timed[j].e end
      j = j + 1
    end
    local colend, col = {}, {}
    for k, it in ipairs(group) do
      local c = 1
      while colend[c] and colend[c] > it.s do c = c + 1 end
      colend[c], col[k] = math.max(it.e, it.s + 1800), c
    end
    local ncol = #colend
    local cw = (x + w - gx - 2) // ncol
    for k, ev in ipairs(group) do
      local by = ypos(ev.s)
      local bh = math.max(ls + 6, ypos(math.max(ev.e, ev.s + 1800)) - by - 2)
      local bx = gx + (col[k] - 1) * cw
      gg:rect(bx, by + 1, cw - 3, bh)
      local inner = cw - 13
      if bh >= ls + lm + 6 then
        text(gg, bx + 5, by + 3, C.hm(ev.s) .. (ev.e > ev.s and (' - ' .. C.hm(ev.e)) or ''), fs)
        local lines = C.wrap(fm, ev.sum, inner)
        local maxl = math.max(1, (bh - ls - 6) // lm)
        for n = 1, math.min(maxl, #lines) do
          local s = lines[n]
          if n == maxl and #lines > maxl then s = C.fit(fm, s .. ' …', inner) end
          text(gg, bx + 5, by + 3 + ls + (n - 1) * lm, s, fm)
        end
      else
        text(gg, bx + 5, by + 3, C.fit(fs, C.hm(ev.s) .. ' ' .. ev.sum, inner), fs)
      end
      hits[#hits + 1] = { x = bx, y = by, w = cw - 3, h = bh, it = ev }
    end
    i = j
  end
  -- now
  if day == env.today then
    local ny = ypos(env.now)
    if ny > top and ny < top + (h1 - h0) * ph then
      gg:line(gx - 10, ny, x + w, ny)
      gg:line(gx - 10, ny + 1, x + w, ny + 1)
    end
  end
  if #later > 0 then
    local parts = {}
    for _k, it in ipairs(later) do parts[#parts + 1] = C.hm(it.s) .. ' ' .. it.sum end
    local s = '+' .. #later .. ' later today: ' .. table.concat(parts, ', ')
    text(gg, x + 6, top + (h1 - h0) * ph + 6, C.fit(fs, s, w - 12), fs)
  end
  if #allday == 0 and #timed == 0 and #later == 0 and #earlier == 0 then
    text(gg, gx + 10, top + ph * 2 + 4, 'No events', fm)
  end
  return hits
end

------------------------------------------------------------------ agenda

local function day_label(env, d)
  local _y, m, dn = C.civil(d)
  local s = C.WDAY_LONG[C.wday(d) + 1] .. ' ' .. dn .. ' ' .. C.MONTH[m]
  if d == env.today then return 'Today, ' .. s end
  if d == env.today + 1 then return 'Tomorrow, ' .. s end
  return s
end

-- the agenda as rows: { day = d } headings and { it = , day = d } events, days with events only
function V.agenda_rows(env, first, n)
  local rows = {}
  local by = C.by_day(env.insts, first, n)
  for d = first, first + n - 1 do
    local list = by[d]
    if list then
      rows[#rows + 1] = { day = d }
      for _k, it in ipairs(list) do rows[#rows + 1] = { it = it, day = d } end
    end
  end
  return rows
end

local HEAD_H, ROW1_H, ROW2_H = 38, 34, 56

local function row_h(r) return r.it and ((r.it.loc and r.it.loc ~= '') and ROW2_H or ROW1_H) or HEAD_H end

-- draws rows from `from` while they fit (gg nil: only measures); -> hits, the first row not drawn
function V.agenda(gg, env, rows, from, x, y, w, h)
  local hits = {}
  local fs, fm = env.font('small'), env.font('medium')
  local ls = env.lh('small')
  local ty, k = y, from
  while k <= #rows do
    local r = rows[k]
    local rh = row_h(r)
    -- a heading needs its first event under it
    local need = rh + ((not r.it and rows[k + 1]) and row_h(rows[k + 1]) or 0)
    if ty + need > y + h then break end
    if gg then
      if r.it then
        local it = r.it
        local tm
        if it.ad then tm = 'all day'
        elseif it.s < r.day * DAY then tm = '...' .. (it.e < (r.day + 1) * DAY and C.hm(it.e) or '')
        else tm = C.hm(it.s) end
        text(gg, x + 8, ty + 4, tm, fs)
        if not it.ad and it.e > it.s and it.s >= r.day * DAY and it.e <= (r.day + 1) * DAY then
          text(gg, x + 8, ty + 4 + ls, C.hm(it.e), fs)
        end
        text(gg, x + 86, ty + 3, C.fit(fm, it.sum, w - 96), fm)
        if it.loc and it.loc ~= '' then text(gg, x + 86, ty + 30, C.fit(fs, it.loc, w - 96), fs) end
      else
        text(gg, x + 4, ty + 8, day_label(env, r.day), fm)
        gg:line(x, ty + HEAD_H - 4, x + w, ty + HEAD_H - 4)
        if r.day == env.today then gg:line(x, ty + HEAD_H - 3, x + w, ty + HEAD_H - 3) end
      end
    end
    if r.it then hits[#hits + 1] = { x = x, y = ty, w = w, h = rh, it = r.it } end
    ty = ty + rh
    k = k + 1
  end
  return hits, k
end

return V
end

-- Calendar for XTOS Licorice, API 2.9 (uses tools/gamekit, src/cal.lua and src/views.lua). A port of
-- KOReader's calendar.koplugin: read-only Google (or any iCal) calendars through their secret iCal
-- address, in Month, Week, Day and Agenda views, and on the lock screen.
--
-- Calendars come from calendars.txt ("Name|address|on" lines; added in Settings or copied over USB
-- into XTApps/calendar/files/). Each is fetched over Wi-Fi when older than the sync interval (or
-- on Sync), read on the device and kept as c<hash>.txt: only events near today and the repeating
-- ones, so the views and the lock screen (lockscreen.lua) work offline.

local C = require('cal')
local V = require('views')
local W, H = kit.W, kit.H
local DAY = 86400
local TAB_H, TOP, BODY_H = 52, 104, 584
local BTN_Y, BTN_H = 716, 64
local MODES = { 'day', 'week', 'month', 'agenda' }
local MODE_LABEL = { day = 'Day', week = 'Week', month = 'Month', agenda = 'Agenda' }
local LOCKS = { 'off', 'agenda', 'day', 'week', 'month' }
local EVERY = { 1, 3, 6, 12, 24 }

local cfg = { ws = 1, every = 6, lock = 'off', mode = 'week', host = '', auth = '' }
local cals = {}
local mode, anchor, back_mode = 'week', 0, nil
local ag = { first = 0, starts = { 1 }, page = 1 }
local screen = 'main'                 -- main | settings
local hits = {}
local status, ERR = nil, nil
local OFF = 0                          -- the UTC offset
local data_ver = 0

local function clock()
  local e, off = C.clock()
  OFF = off
  return e, e + off, (e + off) // DAY       -- UTC, wall seconds, today
end

------------------------------------------------------------------ storage

local function save_cfg()
  kit.write('settings.txt', 'ws=' .. cfg.ws .. '\nevery=' .. cfg.every .. '\nlock=' .. cfg.lock .. '\nmode=' .. mode ..
    '\nhost=' .. cfg.host .. '\nauth=' .. cfg.auth .. '\nplain=' .. (cfg.plain and '1' or '0') ..
    '\ngz=' .. (cfg.gz and 'ok' or ''))
end
local function save_list() kit.write('calendars.txt', C.list_text(cals)) end

local function load_cal(c)
  local events, updated, bytes, packed = C.load_cache(kit.read(C.cache_name(c.url)))
  c.events, c.updated, c.bytes, c.packed = events, events and updated or nil, bytes, packed
end
local function load_all()
  local t = kit.kv(kit.read('settings.txt'))
  cfg.ws = t.ws == '0' and 0 or 1
  cfg.every = tonumber(t.every) or 6
  cfg.host, cfg.auth = t.host or '', t.auth or ''
  cfg.plain = t.plain == '1'           -- this reader could not unpack gzip: ask for the file as it is
  cfg.gz = t.gz == 'ok'                -- gzip has worked here (the lock screen asks for it only then)
  for _k, l in ipairs(LOCKS) do if t.lock == l then cfg.lock = l end end
  for _k, m in ipairs(MODES) do if t.mode == m then mode = m end end
  cals = C.parse_list(kit.read('calendars.txt'))
  for _k, c in ipairs(cals) do load_cal(c) end
  data_ver = data_ver + 1
end

------------------------------------------------------------------ syncing

local sync_q, sync_cur, sync_since, sync_done = nil, nil, nil, 0
local function stale(c, now)
  return not c.updated or now - c.updated > cfg.every * 3600
end
local function syncing() return sync_cur ~= nil end

local function after_sync()
  local bad = {}
  for _k, c in ipairs(cals) do if c.on and c.err then bad[#bad + 1] = c.name .. ': ' .. c.err end end
  status = #bad > 0 and table.concat(bad, '; ') or (sync_done > 0 and 'Synced.' or nil)
  data_ver = data_ver + 1
end

-- -> 'again' when the calendar should be asked once more, as it is (gzip could not be unpacked)
local function take_body(c, resp, via)
  local body, why, what, packed = C.answer(resp, via, true)
  if what == 'gzip' and not cfg.plain then
    cfg.plain = true
    save_cfg()
    return 'again'
  end
  if not body then c.err = why; return end      -- the last whole copy stays
  if (packed or 0) > 0 and not cfg.gz then cfg.gz = true; save_cfg() end
  local bytes = #body
  C.step('read ' .. (bytes // 1024) .. ' KB')
  local e, _wall, today = clock()
  local events = C.parse_ics(body, OFF, today)
  body = nil
  C.free()
  C.step('save')
  kit.write(C.cache_name(c.url), C.cache_text(events, e, OFF, bytes, packed))
  c.events, c.updated, c.bytes, c.packed, c.err = events, e, bytes, packed, nil
  sync_done = sync_done + 1
end

local sync_next
sync_next = function()
  local c = sync_q and table.remove(sync_q, 1)
  if not c then
    sync_q, sync_cur = nil, nil
    C.step('done')
    after_sync()
    return
  end
  sync_cur, sync_since = c, kit.now_ms()
  C.step('download ' .. c.name .. (cfg.plain and '' or ' (gzip)'))
  pcall(function() ctx.net:keep_wifi(5 * 60 * 1000) end)
  local ok, err = pcall(function()
    local opts, via = C.request(c.url, cfg, not cfg.plain)
    ctx.net:request(opts, function(cc, resp)
      if sync_cur ~= c then return end
      local okb, e = pcall(take_body, c, resp, via)
      if not okb then c.err = kit.short(tostring(e), 60) end
      if okb and e == 'again' then table.insert(sync_q, 1, c) end
      sync_cur = nil
      sync_next()
      kit.refresh()
    end)
  end)
  if not ok then
    c.err = 'could not ask: ' .. kit.short(tostring(err), 30)
    sync_cur = nil
    sync_next()
  end
end

-- fetch the shown calendars that are old (all of them when forced, or just `only`)
local function sync(force, only)
  if sync_cur then return end
  local e = clock()
  local q = {}
  for _k, c in ipairs(cals) do
    if c.on and ((only and c == only) or (not only and (force or stale(c, e)))) then q[#q + 1] = c end
  end
  if #q == 0 then
    if force then status = #cals == 0 and 'No calendars: add one in Settings.' or 'No calendar is shown.' end
    return
  end
  for _k, c in ipairs(q) do c.err = nil end
  sync_q, sync_done, status = q, 0, nil
  sync_next()
end

-- a request that never answers is given up after 90 s
local function watchdog()
  if sync_cur and sync_since and (kit.now_ms() or 0) - sync_since > 90000 then
    sync_cur.err = 'no answer'
    sync_cur = nil
    sync_next()
  end
end

------------------------------------------------------------------ the shown period

local vkey, vinsts = nil, {}
local function insts(first, n)
  local key = first .. ':' .. n .. ':' .. data_ver .. ':' .. OFF
  if key ~= vkey then
    vkey = key
    vinsts = C.between(cals, first * DAY, (first + n) * DAY, OFF)
  end
  return vinsts
end
local function env_for(first, n)
  local _e, wall, today = clock()
  return { font = kit.font, lh = kit.line_h, today = today, now = wall, ws = cfg.ws, insts = insts(first, n) }
end

local function agenda_env()
  local env = env_for(ag.first, 60)
  return env, V.agenda_rows(env, ag.first, 60)
end
-- the start row of every agenda page
local function agenda_pages(env, rows)
  local starts, k = { 1 }, 1
  while true do
    local _h, nxt = V.agenda(nil, env, rows, k, 0, TOP, W, BODY_H)
    if nxt > #rows or nxt <= k then break end
    starts[#starts + 1] = nxt
    k = nxt
  end
  return starts
end

local function step(dir)
  if mode == 'day' then anchor = anchor + dir
  elseif mode == 'week' then anchor = anchor + 7 * dir
  elseif mode == 'month' then
    local y, m, d = C.civil(anchor)
    m = m + dir
    if m < 1 then y, m = y - 1, 12 elseif m > 12 then y, m = y + 1, 1 end
    anchor = C.days(y, m, math.min(d, C.month_len(y, m)))
  else
    local env, rows = agenda_env()
    ag.starts = agenda_pages(env, rows)
    if dir > 0 then
      if ag.page < #ag.starts then ag.page = ag.page + 1
      else ag.first, ag.page = ag.first + 60, 1 end
    else
      if ag.page > 1 then ag.page = ag.page - 1
      else
        ag.first = ag.first - 60
        local env2, rows2 = agenda_env()
        ag.starts = agenda_pages(env2, rows2)
        ag.page = #ag.starts
      end
    end
  end
end
local function go_today()
  local _e, _w, today = clock()
  anchor, back_mode = today, nil
  ag.first, ag.page = today, 1
end
local function set_mode(m)
  if m == 'agenda' and mode ~= 'agenda' then ag.first, ag.page = anchor, 1 end
  mode, back_mode = m, nil
  save_cfg()
end

------------------------------------------------------------------ boxes

local function show_event(it)
  local lines = { C.when(it) }
  if it.loc and it.loc ~= '' then lines[#lines + 1] = 'At ' .. it.loc end
  if it.cal and #cals > 1 then lines[#lines + 1] = 'Calendar: ' .. it.cal.name end
  if it.desc and it.desc ~= '' then
    local wrapped = kit.wrap(it.desc, 'small', W - 80)
    local keep = {}
    for k = 1, math.min(#wrapped, 16) do keep[#keep + 1] = wrapped[k] end
    if #wrapped > 16 then keep[#keep] = keep[#keep] .. ' …' end
    lines[#lines + 1] = ''
    lines[#lines + 1] = table.concat(keep, '\n')
  end
  kit.show({ title = it.sum ~= '' and it.sum or '(no title)', lines = lines, rows = { { { 'Close', kit.close } } }, cancel = kit.close })
end

local function host_of(url) return url:match('^%a+://([^/]+)') or url end

local function ask_text(title, value, fn)
  ctx.input:text({ title = title, value = value or '', max_chars = 400 }, function(c, s)
    local ok, e = pcall(fn, s)
    if not ok then ERR = tostring(e) end
    kit.refresh()
  end)
end

local function add_calendar()
  ask_text('Secret iCal address (https://...)', '', function(s)
    if not s or not s:match('%S') then return end
    local url = C.fix_url(s)
    if not url:match('^https?://') then status = 'The address must start with https://'; return end
    for _k, c in ipairs(cals) do if c.url == url then status = 'That calendar is already here.'; return end end
    local guess = host_of(url):find('google', 1, true) and 'Google' or host_of(url)
    ask_text('Name for this calendar', guess, function(name)
      local c = { name = (name and name:match('%S')) and kit.short(name:gsub('|', '/'), 40) or guess, url = url, on = true }
      cals[#cals + 1] = c
      save_list()
      sync(false, c)
    end)
  end)
end

local function calendar_box(c)
  local info = { kit.short(host_of(c.url), 40) .. '/...' }
  if c.err then info[#info + 1] = 'Last sync: ' .. c.err end
  kit.show({
    title = c.name, lines = info, cancel = kit.close,
    rows = {
      { { c.on and 'Hide' or 'Show', function()
          c.on = not c.on; save_list(); data_ver = data_ver + 1; kit.close()
          if c.on and not c.events then sync(false, c) end
        end },
        { 'Rename', function()
          kit.close()
          ask_text('Name for this calendar', c.name, function(s)
            if s and s:match('%S') then c.name = kit.short(s:gsub('|', '/'), 40); save_list() end
          end)
        end } },
      { { 'Delete', function()
          kit.show({ title = 'Delete "' .. c.name .. '"?', lines = { 'Only this list forgets it; the calendar itself is not touched.' },
                     cancel = kit.close, rows = { { { 'Delete', function()
                       for k, x in ipairs(cals) do if x == c then table.remove(cals, k); break end end
                       pcall(function() ctx.storage:remove(C.cache_name(c.url)) end)
                       save_list(); data_ver = data_ver + 1; kit.close()
                     end }, { 'Cancel', kit.close } } } })
        end },
        { 'Close', kit.close } },
    } })
end

-- optional: the rss-opds Worker sends only the events near today (/api/ics), for calendars too
-- big for the reader even packed. Its host, then its login.
local function ask_worker()
  ask_text('Worker host, e.g. rss-opds.you.workers.dev (empty: none)', cfg.host, function(s)
    if s == nil then return end
    cfg.host = s:gsub('^[ 	]+', ''):gsub('[ 	]+$', ''):gsub('^%a+://', ''):gsub('/+$', '')
    if cfg.host == '' then
      cfg.auth = ''
      save_cfg()
      status = 'Worker: off.'
      return
    end
    ask_text('Worker login as user:password (empty: none)', cfg.auth, function(a)
      cfg.auth = (a or ''):gsub('^[ 	]+', ''):gsub('[ 	]+$', '')
      save_cfg()
      sync(true)
    end)
  end)
end

------------------------------------------------------------------ lock screen

local function set_lock(l)
  local L = ctx.lockscreen
  cfg.lock = l
  save_cfg()
  if not L then status = 'This firmware has no app lock screen.'; return end
  local okd, isdef = pcall(function() return L:is_default() end)
  if l ~= 'off' then
    if not (okd and isdef == true) then pcall(function() L:set_default() end) end
    status = 'Lock screen: the ' .. MODE_LABEL[l]:lower() .. ' view.'
  else
    if okd and isdef == true then pcall(function() L:clear_default() end) end
    status = 'Lock screen: off.'
  end
end

------------------------------------------------------------------ drawing

local function ago(e, now)
  local m = math.max(0, now - e) // 60
  if m < 2 then return 'just now' end
  if m < 90 then return m .. ' min ago' end
  if m < 48 * 60 then return (m // 60) .. ' h ago' end
  return (m // 1440) .. ' days ago'
end

local function main_buttons() return { '<', 'Today', '>', syncing() and 'Wait' or 'Sync', 'More' } end
local function settings_buttons() return { 'Back', 'Add', syncing() and 'Wait' or 'Sync now' } end
local function button_rect(k, n)
  local bw = math.floor((W - 24 - (n - 1) * 8) / n)
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function draw_main(gg)
  local tw = W // 4
  for k, m in ipairs(MODES) do
    kit.button(gg, (k - 1) * tw + 4, 4, tw - 8, TAB_H - 8, MODE_LABEL[m], { line_width = m == mode and 4 or 1 })
  end
  if #cals == 0 then
    gg:text(16, 70, 'Calendar', { font = kit.font('large') })
    local y = 130
    for _k, l in ipairs(kit.wrap('No calendars yet. Tap More, then Add, and type the calendar\'s secret iCal address '
        .. '(Google Calendar on the web: Settings > your calendar > Integrate calendar > Secret address in iCal format). '
        .. 'Or copy a calendars.txt with "Name|address" lines into XTApps/calendar/files/ over USB.', 'medium', W - 32)) do
      gg:text(16, y, l, { font = kit.font('medium') })
      y = y + kit.line_h('medium') + 2
    end
    hits = {}
    return
  end
  local title = V.title(mode, mode == 'agenda' and ag.first or anchor, cfg.ws)
  gg:text(12, 62, kit.short(title, 34), { font = kit.font('large') })
  local first, n = V.window(mode, mode == 'agenda' and ag.first or anchor, cfg.ws)
  local env = env_for(first, n)
  if mode == 'month' then hits = V.month(gg, env, anchor, 2, TOP, W - 4, BODY_H)
  elseif mode == 'week' then hits = V.week(gg, env, anchor, 4, TOP, W - 8, BODY_H)
  elseif mode == 'day' then hits = V.day(gg, env, anchor, 4, TOP, W - 8, BODY_H)
  else
    local rows = V.agenda_rows(env, ag.first, 60)
    ag.starts = agenda_pages(env, rows)
    if ag.page > #ag.starts then ag.page = #ag.starts end
    hits = V.agenda(gg, env, rows, ag.starts[ag.page], 4, TOP, W - 8, BODY_H)
    if #rows == 0 then gg:text(16, TOP + 20, 'No events in these 60 days.', { font = kit.font('medium') }) end
    gg:text(W - 70, 70, ag.page .. '/' .. #ag.starts, { font = kit.font('small') })
  end
end

local function setting_rows()
  return {
    { 'Week starts on: ' .. (cfg.ws == 1 and 'Monday' or 'Sunday'), 'ws' },
    { 'Sync when older than: ' .. cfg.every .. ' h', 'every' },
    { 'Lock screen: ' .. (cfg.lock == 'off' and 'off' or MODE_LABEL[cfg.lock]), 'lock' },
    { 'Worker: ' .. (cfg.host ~= '' and kit.short(cfg.host, 30) or 'off (straight to the calendar)'), 'worker' },
  }
end
local CAL_Y, CAL_H, MAX_CALS, OPT_Y, OPT_H = 100, 66, 5, 466, 54

local function draw_settings(gg)
  gg:text(16, 12, 'Settings', { font = kit.font('large') })
  gg:text(16, 64, 'Calendars (tap one to hide, rename or delete)', { font = kit.font('small') })
  local e = clock()
  for k, c in ipairs(cals) do
    if k > MAX_CALS then
      gg:text(16, CAL_Y + (k - 1) * CAL_H + 6, '+' .. (#cals - MAX_CALS) .. ' more: edit calendars.txt over USB', { font = kit.font('small') })
      break
    end
    local y = CAL_Y + (k - 1) * CAL_H
    gg:text(20, y + 6, kit.short(c.name, 30) .. (c.on and '' or '  (hidden)'), { font = kit.font('medium') })
    local info
    if sync_cur == c then info = 'syncing...'
    elseif c.err then info = 'error: ' .. c.err
    elseif c.updated then
      info = #(c.events or {}) .. ' events, ' .. ((c.bytes or 0) // 1024) .. ' KB' ..
        ((c.packed or 0) > 0 and (' (' .. (c.packed // 1024) .. ' KB gzip)') or '') .. ', synced ' .. ago(c.updated, e)
    else info = 'not synced yet' end
    gg:text(20, y + 36, kit.short(info, 46), { font = kit.font('small') })
    gg:line(16, y + CAL_H - 2, W - 16, y + CAL_H - 2)
  end
  if #cals == 0 then gg:text(20, CAL_Y + 10, 'None yet: tap Add.', { font = kit.font('medium') }) end
  local _e, wall = clock()
  local zone = string.format('UTC%s%d', OFF < 0 and '-' or '+', math.abs(OFF) // 3600) .. (OFF % 3600 ~= 0 and string.format(':%02d', math.abs(OFF) % 3600 // 60) or '')
  gg:text(16, OPT_Y - 30, 'Clock: ' .. C.date(wall // DAY) .. ' ' .. C.hm(wall) .. ', ' .. zone, { font = kit.font('small') })
  for k, r in ipairs(setting_rows()) do
    local y = OPT_Y + (k - 1) * OPT_H
    gg:rect(12, y, W - 24, OPT_H - 8)
    gg:text(24, y + 12, r[1], { font = kit.font('medium') })
  end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    if screen == 'settings' then draw_settings(gg) else draw_main(gg) end
    local line = (sync_cur and ('Syncing ' .. kit.short(sync_cur.name, 24) .. '...')) or status or ERR
    if line then gg:text(12, BTN_Y - 26, kit.short(line, 48), { font = kit.font('small') }) end
    local bs = screen == 'settings' and settings_buttons() or main_buttons()
    for k, b in ipairs(bs) do
      local x, y, bw, bh = button_rect(k, #bs)
      kit.button(gg, x, y, bw, bh, b, { font = 'medium' })
    end
    if kit.modal() then kit.draw_modal(gg) end
  end)
  if not ok then pcall(function() gg:text(8, H - 40, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function tap_settings(x, y)
  if y >= CAL_Y and y < CAL_Y + MAX_CALS * CAL_H then
    local c = cals[(y - CAL_Y) // CAL_H + 1]
    if c then calendar_box(c) end
    return
  end
  for k, r in ipairs(setting_rows()) do
    local ry = OPT_Y + (k - 1) * OPT_H
    if y >= ry and y < ry + OPT_H - 8 then
      if r[2] == 'ws' then cfg.ws = 1 - cfg.ws; save_cfg()
      elseif r[2] == 'every' then
        local nxt = EVERY[1]
        for i, v in ipairs(EVERY) do if v == cfg.every then nxt = EVERY[i % #EVERY + 1] end end
        cfg.every = nxt
        save_cfg()
      elseif r[2] == 'worker' then
        ask_worker()
      else
        local nxt = LOCKS[1]
        for i, v in ipairs(LOCKS) do if v == cfg.lock then nxt = LOCKS[i % #LOCKS + 1] end end
        set_lock(nxt)
      end
      return
    end
  end
end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  local bs = screen == 'settings' and settings_buttons() or main_buttons()
  for k, b in ipairs(bs) do
    local bx, by, bw, bh = button_rect(k, #bs)
    if x >= bx and x < bx + bw and y >= by and y < by + bh then
      status = nil
      if b == '<' then step(-1)
      elseif b == '>' then step(1)
      elseif b == 'Today' then go_today()
      elseif b == 'Sync' or b == 'Sync now' then sync(true)
      elseif b == 'More' then screen = 'settings'
      elseif b == 'Back' then screen = 'main'
      elseif b == 'Add' then add_calendar() end
      return
    end
  end
  if screen == 'settings' then tap_settings(x, y); return end
  if y < TAB_H then
    local m = MODES[x // (W // 4) + 1]
    if m then set_mode(m) end
    return
  end
  for _k, h in ipairs(hits) do
    if x >= h.x and x < h.x + h.w and y >= h.y and y < h.y + h.h then
      if h.it then show_event(h.it)
      elseif h.day then
        local from = mode
        anchor = h.day
        set_mode('day')
        back_mode = from
      end
      return
    end
  end
end

local function go_back()
  if kit.modal() then
    if kit.modal().cancel then kit.modal().cancel() end
  elseif screen == 'settings' then screen = 'main'
  elseif back_mode then
    local m = back_mode
    set_mode(m)
  end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    watchdog()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      local g = ev.gesture
      if not kit.modal() and screen == 'main' and (g == 'swipe_left' or g == 'swipe_right') then
        step(g == 'swipe_left' and 1 or -1)
      elseif g == nil or g == 'tap' then
        tap(ev.x or 0, ev.y or 0)
      end
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if ev.key == 'back' then go_back()
      elseif not kit.modal() and screen == 'main' then
        if ev.key == 'left' or ev.key == 'up' then step(-1)
        elseif ev.key == 'right' or ev.key == 'down' then step(1) end
      end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(function()
    load_all()
    go_today()
    -- the reader closed the app during the last sync: say where, don't start one at once, and
    -- when it was unpacking, ask for the file as it is from now on
    local last = kit.read('sync_step.txt')
    if last and last ~= '' and last ~= 'done' then
      status = 'The last sync stopped at: ' .. last .. '.'
      if last:match('^unpack') then
        cfg.plain = true
        save_cfg()
        status = status .. ' Now without gzip.'
      end
      C.step('done')
      return
    end
    sync(false)
  end)
  if not ok then ERR = tostring(e) end
end
function on_leave() pcall(function() ctx.net:keep_wifi(1) end) end

if rawget(_G, '__TEST') then
  __TEST.api = { C = C, V = V, cals = function() return cals end, cfg = cfg, mode = function() return mode end,
                 anchor = function() return anchor end, ag = ag, screen = function() return screen end,
                 status = function() return status end, hits = function() return hits end }
end
